krpano.action:
for(set(h,0), h LT hotspot.count, inc(h),
	if(hotspot[get(h)].style == 'skin_hotspotstyle2',


		txtadd(hs_img, get(hotspot[get(h)].name), '_img');
		addhotspot(get(hs_img), temp_hs, 'css3d');
		hotspot[get(hs_img)].loadstyle(skin_hotspotstyle2_img);
		copy(hotspot[get(hs_img)].ath, hotspot[get(h)].ath);
		copy(hotspot[get(hs_img)].atv, hotspot[get(h)].atv);

		if(scene[get(hotspot[get(h)].linkedscene)].thumburl,
			copy(hotspot[get(hs_img)].url, scene[get(hotspot[get(h)].linkedscene)].thumburl);
		);


		txtadd(hs_tag, get(hotspot[get(h)].name), '_tag');
		addhotspot(get(hs_tag), temp_hs2, 'css3d');
		hotspot[get(hs_tag)].loadstyle(skin_hotspotstyle2_tag);
		copy(hotspot[get(hs_tag)].ath, hotspot[get(h)].ath);
		copy(hotspot[get(hs_tag)].atv, hotspot[get(h)].atv);


		if(scene[get(hotspot[get(h)].linkedscene)].title,
			txtadd(hotspot[get(hs_tag)].html, '[h1]', get(scene[get(hotspot[get(h)].linkedscene)].title), '[/h1]');
		  ,
			txtadd(hotspot[get(hs_tag)].html, '[h1]', get(hotspot[get(h)].linkedscene), '[/h1]');
		);


		update_marker_preview_offset(get(hotspot[get(h)].name));
	);
);

if(global.hs_busy != true,
	set(zorder, 999997);
	tween(alpha, 1.0, 0.2);

	txtadd(hs_tag, get(name), '_tag');
	tween(hotspot[get(hs_tag)].alpha, 1.0, 0.3);

	txtadd(hs_img, get(name), '_img');
	tween(hotspot[get(hs_img)].scale, 1.0, 0.3, easeoutcubic);
	tween(hotspot[get(hs_img)].alpha, 1.0, 0.3, easeoutcubic);
);

if(global.hs_busy != true,
	set(zorder, 40);
	tween(alpha, 0.9, 0.2);

	txtadd(hs_tag, get(name), '_tag');
	tween(hotspot[get(hs_tag)].alpha, 0.0, 0.3);

	txtadd(hs_img, get(name), '_img');
	tween(hotspot[get(hs_img)].scale, 0.3, 0.3, easeoutcubic);
	tween(hotspot[get(hs_img)].alpha, 0.0, 0.3, easeoutcubic);
);

if(linkedscene,
	if(device.handheld,


		if(global.hs_busy != true,
			hotspot2_onover();
			set(global.hs_busy, true);
			copy(global.next_scene, linkedscene);
			copy(global.hs_name, name);
			delayedcall(mobile_preview_dc, 2.0, hotspot2_go_mobile(); );
		);

	  ,


		hotspot2_onout();
		tween(scale, 0.1, 0.25);
		tween(alpha, 0.0, 0.25);
		looktohotspot(get(name), 70, smooth(80,20,100));
		loadscene(get(linkedscene), null, MERGE, BLEND(1));
	);
);
